"""An index fixture serialized by the pre-split code stays readable. Fixture widths are test assumptions."""
from dataclasses import asdict, replace

import pytest

from colonymind.turns import TurnIdempotencyLedger
from colonymind.vector.indexes import EmbeddingIdentity, IndexCatalog, IncompatibleIndex
from colonymind.mind import lesson_match

# Generated by the previous implementation; deliberately not recalculated by the test.
OLD_IDENTITY = ('{"declared_revision":"r1","dimensions":2,"document_format":"raw-text-v1",'
                '"normalization":"unspecified","quantization":"unspecified",'
                '"query_format":"prefix-v1:Retrieve: ","requested_model":"model-a","served_model":"served-a"}')
OLD_FINGERPRINT = '589512b88c361d8058f2aea6f45d53606fa14555dbceaf75b69dc78692914773'


def test_old_generation_opens_and_query_changes_need_no_rebuild(tmp_path):
    catalog = IndexCatalog(TurnIdempotencyLedger(tmp_path / 'turn-idempotency.db'))
    with catalog.ledger._connect() as conn:
        conn.execute('INSERT INTO vector_generations(id,fingerprint,identity_json,status) VALUES(?,?,?,?)',
                     ('prior', OLD_FINGERPRINT, OLD_IDENTITY, 'ready'))
        conn.execute('INSERT INTO vector_active(slot,generation_id) VALUES(1,?)', ('prior',))
    original = EmbeddingIdentity('model-a', 'served-a', 'r1', 2, query_format='prefix-v1:Retrieve: ')
    assert catalog.read_generation(original)['id'] == 'prior'
    changed = replace(original, query_transform='query-adapter-1:' + 'a' * 64)
    assert changed.document_identity == original.document_identity
    assert changed.fingerprint == original.fingerprint == OLD_FINGERPRINT
    assert catalog.read_generation(changed)['id'] == catalog.write_generation(changed)['id'] == 'prior'
    assert catalog.read_generation(replace(changed, query_format='prefix-v1:Other: '))['id'] == 'prior'
    for fields in ({'declared_revision': 'r2'}, {'dimensions': 3}, {'document_format': 'other'},
                   {'request_dimensions': 2}, {'quantization': 'int8'}):
        with pytest.raises(IncompatibleIndex):
            catalog.read_generation(replace(changed, **fields))
    assert len(catalog.generations()) == 1


def test_split_identity_finds_shipped_large_model_bound_and_adapter_does_not(monkeypatch):
    import json
    monkeypatch.delenv(lesson_match.DEPLOYMENT_BOUNDS, raising=False)
    entry = next(item for item in json.loads(lesson_match.BOUNDS.read_text())['measurements']
                 if item['embedding']['requested_model'] == 'Qwen/Qwen3-Embedding-8B')
    fields = {k: v for k, v in entry['embedding'].items() if k != 'fingerprint'}
    original = EmbeddingIdentity(**fields, query_transform='identity')
    assert lesson_match.bound_for(asdict(original)) == (entry['bound'], 'measured')
    changed = replace(original, query_transform='query-adapter-1:' + 'b' * 64)
    assert lesson_match.bound_for(asdict(changed))[1] == 'unmeasured'


def test_query_only_changes_resume_a_build_and_corrupt_identity_does_not_pass(tmp_path):
    catalog = IndexCatalog(TurnIdempotencyLedger(tmp_path / 'turn-idempotency.db'))
    original = EmbeddingIdentity('model-a', 'served-a', 'r1', 2)
    catalog.initialize(original, legacy_exists=False)
    building = catalog.begin(original)
    changed = replace(original, query_format='prefix-v1:Other: ', query_transform='query-adapter-1:' + 'c' * 64)
    assert catalog.begin(changed)['id'] == building['id']
    assert catalog.write_generation(changed)['id'] == building['id']
    catalog.promote(building['id'], changed)
    assert catalog.read_generation(changed)['id'] == building['id']
    with catalog.ledger._connect() as conn:
        conn.execute("UPDATE vector_generations SET fingerprint='corrupt' WHERE id=?", (building['id'],))
    with pytest.raises(IncompatibleIndex):
        catalog.read_generation(changed)


def test_pipeline_exposes_document_identity_and_query_transform(monkeypatch):
    from types import SimpleNamespace
    from colonymind.vector.config import EmbeddingConfig
    from colonymind.vector.embedder import EmbeddingPipeline
    provider = SimpleNamespace(_config=EmbeddingConfig(provider='openai_api', model_id='model-a', dimensions=2),
                               _served_model='served-a', dimensions=2)
    first = EmbeddingPipeline(provider)
    adapted = EmbeddingPipeline(provider, query_transform='query-adapter-1:' + 'd' * 64)
    assert first.document_identity == adapted.document_identity
    assert adapted.index_identity.query_transform == adapted.query_transform
    assert first.index_identity.fingerprint == adapted.index_identity.fingerprint
